import java.util.Optional;

record Request(String userId, String payload, boolean authenticated) {}
record Response(String handledBy, String body) {}

abstract class Handler {
    private Handler next;

    Handler linkWith(Handler next) {
        this.next = next;
        return next; // enables head.linkWith(a).linkWith(b)
    }

    final Optional<Response> handle(Request req) {
        if (canHandle(req)) return Optional.of(process(req));
        if (next != null) return next.handle(req);
        return Optional.empty(); // caller maps this to terminal handler
    }

    protected abstract boolean canHandle(Request req);
    protected abstract Response process(Request req);
}

final class AuthHandler extends Handler {
    protected boolean canHandle(Request req) { return !req.authenticated(); }
    protected Response process(Request req) {
        return new Response("auth", "401 unauthorized");
    }
}

final class BusinessHandler extends Handler {
    protected boolean canHandle(Request req) { return req.authenticated(); }
    protected Response process(Request req) {
        return new Response("business", "ok:" + req.payload());
    }
}

// Build once at startup. Order IS the policy.
Handler head = new AuthHandler();
Handler terminal = new BusinessHandler();
head.linkWith(terminal);

// Client knows only the head. Trade-off: one-line call,
// full routing logic hidden inside the chain.
Response out = head.handle(new Request("u1", "pay", true))
    .orElse(new Response("default", "422 unprocessable"));

// Broadcast variant (filters): same interface, different base.
// Each handler always calls next after acting:
